// TypeScript side of the shared Python/TypeScript DSL conformance corpus.
//
// Each tests/conformance/*.sexpr case has a committed *.canonical.json generated by
// scripts/generate_conformance_corpus.py from the Python implementation (the
// authority). The TS parse must project to the same canonical tree, and the
// TS emit must round-trip through fromDSLString to that same tree.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  fromDSLString,
  toDSL,
  type ParsedDSL,
  type StrategyMetadata,
} from '@llamatrade/core/strategy/serializer';
import type {
  Block,
  BlockId,
  ConditionExpression,
  ConditionOperand,
  IfBlock,
  IndicatorRef,
  StrategyTree,
  WeightBlock,
} from '@llamatrade/core/strategy/types';
import {
  DSL_COMPARISON_OPS,
  DSL_CROSSOVER_OPS,
  DSL_FILTER_CRITERIA,
  DSL_INDICATORS,
  DSL_LOGICAL_OPS,
  DSL_METRICS,
  DSL_PRICE_FIELDS,
  DSL_REBALANCE_FREQUENCIES,
  DSL_SELECT_DIRECTIONS,
  DSL_WEIGHT_METHODS,
} from '@llamatrade/core/strategy/vocabulary';
import { describe, it, expect } from 'vitest';

// Canonical JSON schema — mirrors llamatrade_dsl.to_json exactly.

interface NumericJSON {
  type: 'numeric';
  value: number;
}

interface PriceJSON {
  type: 'price';
  symbol: string;
  field?: string;
}

interface IndicatorJSON {
  type: 'indicator';
  name: string;
  symbol: string;
  params?: number[];
  output?: string;
}

interface MetricJSON {
  type: 'metric';
  name: string;
  symbol: string;
  period?: number;
}

type ValueJSON = NumericJSON | PriceJSON | IndicatorJSON | MetricJSON;

interface ComparisonJSON {
  type: 'comparison';
  operator: string;
  left: ValueJSON;
  right: ValueJSON;
}

interface CrossoverJSON {
  type: 'crossover';
  direction: 'above' | 'below';
  fast: ValueJSON;
  slow: ValueJSON;
}

type ConditionJSON = ComparisonJSON | CrossoverJSON;

interface AssetJSON {
  type: 'asset';
  symbol: string;
  weight?: number;
}

interface WeightJSON {
  type: 'weight';
  method: string;
  lookback?: number;
  top?: number;
  children: BlockJSON[];
}

interface GroupJSON {
  type: 'group';
  name: string;
  weight?: number;
  children: BlockJSON[];
}

interface IfJSON {
  type: 'if';
  condition: ConditionJSON;
  then: BlockJSON;
  else_block?: BlockJSON;
}

interface FilterJSON {
  type: 'filter';
  by: string;
  select_direction: string;
  select_count: number;
  lookback?: number;
  children: BlockJSON[];
}

interface StrategyJSON {
  type: 'strategy';
  name: string;
  rebalance?: string;
  benchmark?: string;
  description?: string;
  children: BlockJSON[];
}

type BlockJSON = AssetJSON | WeightJSON | GroupJSON | IfJSON | FilterJSON | StrategyJSON;

// Canonicalizer: TS StrategyTree -> canonical JSON.

const TIMEFRAME_TO_REBALANCE: Record<string, string> = {
  '1D': 'daily',
  '1W': 'weekly',
  '1M': 'monthly',
  '3M': 'quarterly',
  '1Y': 'annually',
};

const PERIOD_TO_LOOKBACK: Record<string, number> = {
  '1m': 21,
  '3m': 63,
  '6m': 126,
  '12m': 252,
};

const COMPARATOR_TO_OPERATOR: Record<string, string> = {
  gt: '>',
  lt: '<',
  gte: '>=',
  lte: '<=',
  eq: '=',
  neq: '!=',
};

function canonicalize(parsed: ParsedDSL): StrategyJSON {
  const root = parsed.tree.blocks[parsed.tree.rootId];
  if (!root || root.type !== 'root') {
    throw new Error('Parsed tree has no root block');
  }

  const out: StrategyJSON = {
    type: 'strategy',
    name: parsed.metadata.name ?? root.name,
    children: canonChildren(root.childIds, parsed.tree, null),
  };

  const rebalance = parsed.metadata.timeframe
    ? TIMEFRAME_TO_REBALANCE[parsed.metadata.timeframe]
    : undefined;
  if (rebalance) out.rebalance = rebalance;
  if (parsed.metadata.benchmark) out.benchmark = parsed.metadata.benchmark;
  if (parsed.metadata.description) out.description = parsed.metadata.description;

  return out;
}

function canonChildren(
  childIds: BlockId[],
  tree: StrategyTree,
  parentWeight: WeightBlock | null
): BlockJSON[] {
  const out: BlockJSON[] = [];

  for (const id of childIds) {
    const block = tree.blocks[id];
    if (!block) throw new Error(`Missing block ${id}`);
    // Else blocks are folded into their if sibling.
    if (block.type === 'else') continue;
    if (block.type === 'if') {
      out.push(canonIf(block, childIds, tree));
      continue;
    }
    out.push(canonBlock(block, tree, parentWeight));
  }

  return out;
}

function canonSingleChild(childIds: BlockId[], tree: StrategyTree, context: string): BlockJSON {
  if (childIds.length !== 1) {
    throw new Error(`${context} must hold exactly one block, got ${childIds.length}`);
  }
  const child = tree.blocks[childIds[0]];
  if (!child) throw new Error(`Missing block ${childIds[0]}`);
  return canonBlock(child, tree, null);
}

function canonIf(ifBlock: IfBlock, siblingIds: BlockId[], tree: StrategyTree): IfJSON {
  const out: IfJSON = {
    type: 'if',
    condition: canonCondition(ifBlock.condition),
    then: canonSingleChild(ifBlock.childIds, tree, `then of if ${ifBlock.id}`),
  };

  for (const siblingId of siblingIds) {
    const sibling = tree.blocks[siblingId];
    if (sibling && sibling.type === 'else' && sibling.ifBlockId === ifBlock.id) {
      out.else_block = canonSingleChild(sibling.childIds, tree, `else of if ${ifBlock.id}`);
      break;
    }
  }

  return out;
}

function canonBlock(block: Block, tree: StrategyTree, parentWeight: WeightBlock | null): BlockJSON {
  switch (block.type) {
    case 'asset': {
      const out: AssetJSON = { type: 'asset', symbol: block.symbol };
      const allocation = parentWeight?.allocations[block.id];
      if (allocation !== undefined) out.weight = allocation;
      return out;
    }
    case 'group': {
      const out: GroupJSON = {
        type: 'group',
        name: block.name,
        children: canonChildren(block.childIds, tree, null),
      };
      const allocation = parentWeight?.allocations[block.id];
      if (allocation !== undefined) out.weight = allocation;
      return out;
    }
    case 'weight': {
      const out: WeightJSON = {
        type: 'weight',
        method: block.method.replace(/_/g, '-'),
        children: canonChildren(block.childIds, tree, block),
      };
      if (block.lookbackDays != null) out.lookback = block.lookbackDays;
      if (block.top != null) out.top = block.top;
      return out;
    }
    case 'filter': {
      const lookback = PERIOD_TO_LOOKBACK[block.config.period];
      if (lookback === undefined) {
        throw new Error(`Unknown filter period: ${block.config.period}`);
      }
      return {
        type: 'filter',
        by: block.config.sortBy,
        select_direction: block.config.selection,
        select_count: block.config.count,
        lookback,
        children: canonChildren(block.childIds, tree, null),
      };
    }
    default:
      throw new Error(`Unexpected block type in canonical projection: ${block.type}`);
  }
}

function canonCondition(condition: ConditionExpression): ConditionJSON {
  if (condition.comparator === 'cross_above' || condition.comparator === 'cross_below') {
    return {
      type: 'crossover',
      direction: condition.comparator === 'cross_above' ? 'above' : 'below',
      fast: canonOperand(condition.left),
      slow: canonOperand(condition.right),
    };
  }

  const operator = COMPARATOR_TO_OPERATOR[condition.comparator];
  if (!operator) throw new Error(`Unknown comparator: ${condition.comparator}`);
  return {
    type: 'comparison',
    operator,
    left: canonOperand(condition.left),
    right: canonOperand(condition.right),
  };
}

function canonOperand(operand: ConditionOperand): ValueJSON {
  switch (operand.type) {
    case 'number':
      return { type: 'numeric', value: operand.value };
    case 'price': {
      const out: PriceJSON = { type: 'price', symbol: operand.symbol };
      if (operand.field !== 'close' && operand.field !== 'current') out.field = operand.field;
      return out;
    }
    case 'metric': {
      const out: MetricJSON = { type: 'metric', name: operand.metric, symbol: operand.symbol };
      if (operand.period != null) out.period = operand.period;
      return out;
    }
    case 'indicator':
      return canonIndicator(operand);
  }
}

function canonIndicator(ind: IndicatorRef): IndicatorJSON {
  const requirePeriod = (): number => {
    if (ind.period == null) throw new Error(`Indicator ${ind.indicator} is missing a period`);
    return ind.period;
  };

  switch (ind.indicator) {
    case 'sma':
    case 'ema':
    case 'rsi':
    case 'atr':
    case 'adx':
    case 'cci':
    case 'mfi':
      return { type: 'indicator', name: ind.indicator, symbol: ind.symbol, params: [requirePeriod()] };
    case 'williams_r':
      return { type: 'indicator', name: 'williams-r', symbol: ind.symbol, params: [requirePeriod()] };
    case 'macd_line':
    case 'macd_signal': {
      if (ind.fastPeriod == null || ind.slowPeriod == null || ind.signalPeriod == null) {
        throw new Error('MACD indicator is missing periods');
      }
      return {
        type: 'indicator',
        name: 'macd',
        symbol: ind.symbol,
        params: [ind.fastPeriod, ind.slowPeriod, ind.signalPeriod],
        output: ind.indicator === 'macd_line' ? 'line' : 'signal',
      };
    }
    case 'bb_upper':
    case 'bb_middle':
    case 'bb_lower': {
      if (ind.stdDev == null) throw new Error('Bollinger indicator is missing stdDev');
      return {
        type: 'indicator',
        name: 'bbands',
        symbol: ind.symbol,
        params: [requirePeriod(), ind.stdDev],
        output: ind.indicator.slice(3),
      };
    }
    case 'stochastic_k':
    case 'stochastic_d':
      return {
        type: 'indicator',
        name: 'stoch',
        symbol: ind.symbol,
        params: [requirePeriod(), 3, 3],
        output: ind.indicator === 'stochastic_k' ? 'k' : 'd',
      };
    case 'obv':
    case 'vwap':
      return { type: 'indicator', name: ind.indicator, symbol: ind.symbol };
  }
}

// Corpus loading.

const CORPUS_DIR = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../../../../../tests/conformance'
);

const caseFiles = fs
  .readdirSync(CORPUS_DIR)
  .filter((file) => file.endsWith('.sexpr'))
  .sort();

function parseOrThrow(dsl: string): ParsedDSL {
  const parsed = fromDSLString(dsl);
  if (!parsed) throw new Error('fromDSLString returned null');
  return parsed;
}

function metadataFor(parsed: ParsedDSL): StrategyMetadata {
  const { name, timeframe, description, benchmark } = parsed.metadata;
  if (!name || !timeframe) throw new Error('Corpus cases must carry a name and :rebalance');
  const metadata: StrategyMetadata = { name, timeframe };
  if (description !== undefined) metadata.description = description;
  if (benchmark !== undefined) metadata.benchmark = benchmark;
  return metadata;
}

describe('DSL conformance corpus', () => {
  it('has at least 10 cases', () => {
    expect(caseFiles.length).toBeGreaterThanOrEqual(10);
  });

  describe.each(caseFiles)('%s', (file) => {
    const sexpr = fs.readFileSync(path.join(CORPUS_DIR, file), 'utf8');
    const canonical = JSON.parse(
      fs.readFileSync(path.join(CORPUS_DIR, file.replace(/\.sexpr$/, '.canonical.json')), 'utf8')
    ) as StrategyJSON;

    it('parses to the canonical tree', () => {
      expect(canonicalize(parseOrThrow(sexpr))).toEqual(canonical);
    });

    it('round-trips through toDSL to the same canonical tree', () => {
      const first = parseOrThrow(sexpr);
      const emitted = toDSL(first.tree, metadataFor(first));

      const second = parseOrThrow(emitted);
      expect(canonicalize(second)).toEqual(canonical);

      // The emitter must be stable across a parse/emit cycle.
      expect(toDSL(second.tree, metadataFor(second))).toBe(emitted);
    });
  });
});

describe('DSL vocabulary parity with the backend grammar', () => {
  const vocabulary = JSON.parse(
    fs.readFileSync(path.join(CORPUS_DIR, 'vocabulary.json'), 'utf8')
  ) as Record<string, string[]>;

  const tables: Record<string, readonly string[]> = {
    comparison_ops: DSL_COMPARISON_OPS,
    crossover_ops: DSL_CROSSOVER_OPS,
    filter_criteria: DSL_FILTER_CRITERIA,
    indicators: DSL_INDICATORS,
    logical_ops: DSL_LOGICAL_OPS,
    metrics: DSL_METRICS,
    price_fields: DSL_PRICE_FIELDS,
    rebalance_frequencies: DSL_REBALANCE_FREQUENCIES,
    select_directions: DSL_SELECT_DIRECTIONS,
    weight_methods: DSL_WEIGHT_METHODS,
  };

  it('covers every table the generator emits', () => {
    expect(Object.keys(tables).sort()).toEqual(Object.keys(vocabulary).sort());
  });

  it.each(Object.keys(tables))('matches the generated %s', (key) => {
    expect([...tables[key]]).toEqual(vocabulary[key]);
  });

  it('reads back and re-emits every operator the backend accepts', () => {
    for (const operator of [...DSL_COMPARISON_OPS, ...DSL_CROSSOVER_OPS]) {
      const dsl = `(strategy "Ops" :rebalance daily (if (${operator} (rsi SPY 14) 50) (asset SPY)))`;
      const parsed = parseOrThrow(dsl);
      expect(toDSL(parsed.tree, metadataFor(parsed))).toContain(
        `(${operator} (rsi SPY 14) 50)`
      );
    }
  });

  it('never emits an operator the backend rejects', () => {
    const accepted = new Set<string>([...DSL_COMPARISON_OPS, ...DSL_CROSSOVER_OPS]);
    for (const operator of Object.values(COMPARATOR_TO_OPERATOR)) {
      expect(accepted.has(operator)).toBe(true);
    }
  });
});

describe('retired strategy keywords are rejected (parity with backend parser)', () => {
  it.each([':stop-loss-pct 5', ':take-profit-pct 15', ':position-size 50'])(
    'rejects %s',
    (retired) => {
      const dsl = `(strategy "Retired" :rebalance daily ${retired} (weight :method equal (asset SPY)))`;
      expect(fromDSLString(dsl)).toBeNull();
    }
  );
});
